char* EncodeVarint64(char* dst, uint64_t v) {
    unsigned char* ptr = reinterpret_cast<unsigned char*>(dst);
    while (v >= 0x80) {
        *ptr++ = static_cast<unsigned char>((v & 0x7F) | 0x80);
        v >>= 7;
    }
    *ptr++ = static_cast<unsigned char>(v);
    return reinterpret_cast<char*>(ptr);
}

// Test cases
int main() {
    char buf[10];
    // Test v = 0
    char* end = EncodeVarint64(buf, 0);
    if (end - buf != 1 || buf[0] != 0x00) return 1;

    // Test v = 128
    end = EncodeVarint64(buf, 128);
    if (end - buf != 2 || buf[0] != 0x80 || buf[1] != 0x01) return 1;

    // Test v = 0xFFFFFFFFFFFFFFFF
    end = EncodeVarint64(buf, 0xFFFFFFFFFFFFFFFF);
    if (end - buf != 10) return 1;

    return 0;
}

